export type Item = {
  type: string;
};

export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: { op: string; items: Item[] }[];
};

export type ScenarioResult = {
  results: { premium: number }[];
};

const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
};
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const PROCESSING_FEE = 5;

const percentOf = (amount: number, percent: number): number =>
  (amount * percent) / 100;

const roundInMHPCOsFavour = (premium: number): number => Math.ceil(premium);

const policyBasePremium = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUM_BY_ITEM_TYPE[item.type], 0);

const quotePremium = (items: Item[]): number => {
  const basePremium = policyBasePremium(items);
  const withFirstInsuranceSurcharge =
    basePremium + percentOf(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT);
  return roundInMHPCOsFavour(withFirstInsuranceSurcharge + PROCESSING_FEE);
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step) => ({
    premium: quotePremium(step.items),
  })),
});

