import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Base premiums: single main items (each + 10% first insurance + 5 G fee) ---
  it("quotes an empty item list as 5 G (processing fee only)", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    };

    expect(runScenario(scenario)).toEqual({ results: [{ premium: 5 }] });
  });
  it("quotes a plain sword (base 100 G) as 115 G", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "sword" }] }],
    };

    expect(runScenario(scenario)).toEqual({ results: [{ premium: 115 }] });
  });
  it("quotes a plain amulet (base 60 G) as 71 G", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "amulet" }] }],
    };

    expect(runScenario(scenario)).toEqual({ results: [{ premium: 71 }] });
  });
  it("quotes a plain staff (base 80 G) as 93 G", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "staff" }] }],
    };

    expect(runScenario(scenario)).toEqual({ results: [{ premium: 93 }] });
  });
  it("quotes a plain potion (base 40 G) as 49 G", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "potion" }] }],
    };

    expect(runScenario(scenario)).toEqual({ results: [{ premium: 49 }] });
  });

  // --- Components and the building block of 3 alike ---
  it("quotes 2 runes as base premium 50 G", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
    };

    // base 50 + 10 % first insurance (5) + 5 fee = 60
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 60 }] });
  });
  it("quotes 3 runes as base premium 60 G (block applies)", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }],
        },
      ],
    };

    // base 60 (block) + 10 % first insurance (6) + 5 fee = 71
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 71 }] });
  });
  it("quotes 4 runes as base premium 100 G (no block — block requires exactly 3)", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "rune" },
            { type: "rune" },
            { type: "rune" },
            { type: "rune" },
          ],
        },
      ],
    };

    // base 100 (no block) + 10 % first insurance (10) + 5 fee = 115
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 115 }] });
  });
  it("quotes 7 runes as base premium 175 G", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: Array.from({ length: 7 }, () => ({ type: "rune" })),
        },
      ],
    };

    // base 175 (7 x 25, no block) + 10 % first insurance (17.5) + 5 fee
    // = 197.5, rounded up in the MHPCO's favour = 198
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 198 }] });
  });
  it("quotes 2 runes + 1 moonstone as base premium 75 G (no block: different types)", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }],
        },
      ],
    };

    // "alike" means the same type: 2 runes (50) + 1 moonstone (25) = 75 base,
    // no block. + 10 % first insurance (7.5) + 5 fee = 87.5, rounded up = 88
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 88 }] });
  });
  it("quotes 3 runes + 3 moonstones as base premium 120 G (two separate blocks)", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            ...Array.from({ length: 3 }, () => ({ type: "rune" })),
            ...Array.from({ length: 3 }, () => ({ type: "moonstone" })),
          ],
        },
      ],
    };

    // each type forms its own block: 60 + 60 = 120 base
    // + 10 % first insurance (12) + 5 fee = 137
    expect(runScenario(scenario)).toEqual({ results: [{ premium: 137 }] });
  });

  // --- Item-specific premium modifiers ---
  it.todo("adds a 50 % curse surcharge to a cursed sword (100 G base -> 150 G)");
  it.todo("adds a 30 % surcharge for a sword with exactly enchantment 5");
  it.todo("adds no high-enchantment surcharge for a sword with enchantment 4");
  it.todo("applies both curse and high-enchantment surcharges to a cursed sword with enchantment 5");
  it.todo("applies the curse surcharge only to the cursed item on a multi-item policy (cursed sword + plain amulet -> 210 G before further modifiers and fee)");

  // --- Policy-wide premium modifiers ---
  it.todo("applies a 20 % loyalty discount for a customer with exactly 2 years with MHPCO");
  it.todo("applies no loyalty discount for a customer with 1 year with MHPCO");
  it.todo("applies a 10 % first-insurance surcharge to the policy base premium");
  it.todo("applies a 15 % follow-up discount on the customer's second quote");
  it.todo("adds the 5 G processing fee at the very end");

  // --- Rounding ---
  it.todo("rounds a premium of 197.5 G up to 198 G (MHPCO's favor)");
  it.todo("rounds a payout of 350.5 G down to 350 G (MHPCO's favor)");

  // --- Claims: standard reimbursement ---
  it.todo("pays out 400 G for a steel sword with enchantment 3 damaged by 500 G (deductible 100 G)");
  it.todo("pays out 100 G for a rune damaged by 200 G (no enchantment or material)");

  // --- Claims: special clauses ---
  it.todo("pays out 400 G for a steel sword with enchantment 9 damaged by 1000 G (50 % clause, then deductible)");
  it.todo("pays out 400 G for a dragon-material sword with exactly enchantment 8 damaged by 1000 G");
  it.todo("pays out 700 G for a dragon-material sword with enchantment 5 damaged by 800 G (full reimbursement, then deductible)");
  it.todo("pays out 400 G for a dragon-material sword with enchantment 9 damaged by 1000 G (the 50 % rule wins)");

  // --- Claims: deductible per damage event ---
  it.todo("pays out 600 G when a dragon attack damages an insured sword (500 G) and an insured amulet (300 G) — one deductible per damaged item");

  // --- Claims: cap ---
  it.todo("reports the remaining cap as twice the insurance sum minus the payout for a single sword policy");
  it.todo("caps a policy covering a sword and an amulet at 3200 G (insurance sum 1600 G)");
  it.todo("caps a policy covering two swords at 4000 G (insurance sum 2000 G)");
  it.todo("caps a cursed sword policy at 2000 G — premium modifiers do not raise the cap");
  it.todo("caps a policy covering a sword and 3 runes at 3500 G (insurance sum 1750 G) — the block discount affects the premium only");
  it.todo("exhausts the cap across two successive 1500 G claims: payout 1400 G / remaining 600 G, then payout 600 G / remaining 0 G");
  it.todo("treats two damage entries of the same item type as separate damages, each with its own deductible");

  // --- Integration examples ---
  it.todo("quotes 165 G for a newcomer (0 years, no previous contract) with a cursed steel sword of enchantment 3");
  it.todo("quotes 160 G for a 3-year customer's second contract covering a cursed steel sword of enchantment 7");

  // --- Errors ---
  it.todo("rejects a quote containing an item with an unknown type");
  it.todo("rejects a claim whose damage references an item not covered by the policy");
  it.todo("rejects a claim whose damage references an unknown item type");
  it.todo("rejects a claim with more damage entries of a type than the policy covers");
  it.todo("rejects a claim containing a damage entry with a negative amount");

  // --- CLI ---
  it.todo("CLI reads a scenario from stdin and writes the results as JSON to stdout");
  it.todo("CLI exits with a non-zero status and writes to stderr when the scenario is invalid");
});

