export type Item = {
  type: string;
  cursed?: boolean;
};

export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: { op: string; items: Item[] }[];
};

export type ScenarioResult = {
  results: { premium: number }[];
};

const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const CURSE_SURCHARGE_PERCENT = 50;
const PROCESSING_FEE = 5;

const percentOf = (amount: number, percent: number): number =>
  (amount * percent) / 100;

const roundInMHPCOsFavour = (premium: number): number => Math.ceil(premium);

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const countByType = (items: Item[]): Map<string, number> =>
  items.reduce(
    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
    new Map<string, number>(),
  );

const formsBuildingBlock = (count: number): boolean => count === BLOCK_SIZE;

const basePremiumForAlikeItems = (type: string, count: number): number =>
  formsBuildingBlock(count)
    ? BLOCK_BASE_PREMIUM
    : count * BASE_PREMIUM_BY_ITEM_TYPE[type];

const policyBasePremium = (items: Item[]): number =>
  [...countByType(items)]
    .map(([type, count]) => basePremiumForAlikeItems(type, count))
    .reduce((total, alikeItemsPremium) => total + alikeItemsPremium, 0);

const itemBasePremium = (item: Item): number =>
  BASE_PREMIUM_BY_ITEM_TYPE[item.type];

/**
 * Item-specific modifiers are percentages of the AFFECTED ITEM's own base
 * premium — unlike policy-wide modifiers, which apply to the policy base.
 */
const surchargePercentFor = (item: Item): number =>
  item.cursed ? CURSE_SURCHARGE_PERCENT : 0;

const itemSurcharges = (items: Item[]): number =>
  items.reduce(
    (total, item) =>
      total + percentOf(itemBasePremium(item), surchargePercentFor(item)),
    0,
  );

const quotePremium = (items: Item[]): number => {
  const basePremium = policyBasePremium(items);
  return roundInMHPCOsFavour(
    basePremium +
      itemSurcharges(items) +
      percentOf(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT) +
      PROCESSING_FEE,
  );
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step) => ({
    premium: quotePremium(step.items),
  })),
});

