const roundPayoutDown = (payout: number): number => Math.floor(payout);

const insuranceSum = (items: Item[]): number =>
  items.reduce((sum, item) => sum + INSURANCE_VALUE_BY_ITEM_TYPE[item.type], 0);

/** The deductible applies once per damaged item, not once per incident. */
const payoutFor = (incident: Incident): number =>
  incident.damages.reduce(
    (total, damage) => total + damage.amount - DEDUCTIBLE,
    0,
  );

const claimResult = (step: Step, scenario: Scenario): ClaimResult => {
  const policyItems = scenario.steps[step.policy ?? 0].items ?? [];
  const cap = CAP_MULTIPLE * insuranceSum(policyItems);
  const payout = roundPayoutDown(payoutFor(step.incident!));
  return { payout, remainingCap: cap - payout };
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step, precedingSteps) =>
    step.op === "claim"
      ? claimResult(step, scenario)
      : {
          premium: quotePremium(
            step.items ?? [],
            scenario.customer,
            precedingSteps,
          ),
        },
  ),
});

