 * remaining cap, letting a claimant raise their own ceiling.
 */
const rejectNegativeDamages = (
  incident: Incident,
  _policyItems: Item[],
): void => {
  for (const damage of incident.damages) {
    if (damage.amount < 0) {
      throw new Error(`damage amount cannot be negative: ${damage.amount}`);
    }
  }
};

/**
 * Every way a claim can be malformed, checked before a single G is settled.
 * The spec rejects the WHOLE claim in each case rather than dropping the
 * offending entry, so all of these run up front for the entire incident.
 *
 * The rules stay separate functions because each throws for a distinct reason
 * with a distinct message, and they share one `(incident, policyItems)`
 * signature so this list can call them uniformly — adding a rule means adding
 * a name here, not threading a new argument. `rejectNegativeDamages` ignores
 * the policy items; paying that unused parameter is what buys the uniformity.
 */
const CLAIM_VALIDATIONS: ((incident: Incident, policyItems: Item[]) => void)[] =
  [rejectNegativeDamages, rejectSurplusDamages];

const rejectMalformedClaim = (
  incident: Incident,
  policyItems: Item[],
): void => {
  for (const validate of CLAIM_VALIDATIONS) {
    validate(incident, policyItems);
  }
};

